scene:
let time = 0;
const cx = () => W()/2, cy = () => H()/2;
const clearR = () => Math.min(W(),H())*0.28;

const bands = [
  {yFrac:0.12, amp:26, freq:0.005, speed:0.06, color:PALETTE[1], alpha:0.30, w:2.2},
  {yFrac:0.20, amp:18, freq:0.008, speed:-0.09, color:PALETTE[0], alpha:0.22, w:1.4},
  {yFrac:0.85, amp:24, freq:0.006, speed:0.08, color:PALETTE[1], alpha:0.28, w:2},
  {yFrac:0.92, amp:16, freq:0.009, speed:-0.05, color:PALETTE[2], alpha:0.20, w:1.2}
];

function drawVein(x1,y1,x2,y2,x3,y3, alpha){
  ctx.beginPath();
  ctx.moveTo(x1,y1);
  ctx.quadraticCurveTo(x2,y2,x3,y3);
  ctx.strokeStyle = PALETTE[2];
  ctx.globalAlpha = alpha;
  ctx.lineWidth = 1.4;
  ctx.stroke();
  ctx.globalAlpha = 1;
}

function makeParticle(){
  const side = Math.random();
  let x;
  if(side<0.5) x = Math.random()*W()*0.4;
  else x = W() - Math.random()*W()*0.4;
  return {
    x,
    y: H() + Math.random()*100,
    r: 1+Math.random()*2.6,
    vy: 0.25+Math.random()*0.5,
    drift: (Math.random()-0.5)*0.3,
    phase: Math.random()*Math.PI*2,
    trail: [],
    hueMix: Math.random()
  };
}

const N = 70;
const particles = [];
for(let i=0;i<N;i++){
  particles.push(makeParticle());
}

function draw(){
  const w = W(), h = H();
  time += 0.008;

  bands.forEach(b=>{
    const y0 = h*b.yFrac;
    ctx.beginPath();
    ctx.moveTo(0, y0);
    for(let x=0;x<=w;x+=8){
      const yy = y0 + Math.sin(x*b.freq + time*b.speed*10)*b.amp;
      ctx.lineTo(x,yy);
    }
    ctx.strokeStyle = b.color;
    ctx.globalAlpha = b.alpha;
    ctx.lineWidth = b.w;
    ctx.shadowColor = b.color;
    ctx.shadowBlur = 8;
    ctx.stroke();
    ctx.shadowBlur = 0;
    ctx.globalAlpha = 1;
  });

  const pulse = 0.25 + 0.15*Math.sin(time*0.7);
  drawVein(0, h*0.02, w*0.18, h*0.1, w*0.35, h*0.02, pulse);
  drawVein(w, h*0.98, w*0.82, h*0.9, w*0.65, h*0.98, pulse);
  drawVein(0, h*0.98, w*0.15, h*0.88, w*0.3, h*0.98, pulse*0.8);
  drawVein(w, h*0.02, w*0.85, h*0.12, w*0.7, h*0.02, pulse*0.8);

  const centerX = cx(), centerY = cy(), rClear = clearR();
  particles.forEach(p=>{
    p.trail.push({x:p.x,y:p.y});
    if(p.trail.length>10) p.trail.shift();

    p.y -= p.vy;
    p.x += Math.sin(time*2+p.phase)*p.drift;

    const dx = p.x-centerX, dy = p.y-centerY;
    const dist = Math.sqrt(dx*dx+dy*dy);
    if(dist < rClear){
      const push = (rClear-dist)/rClear;
      p.x += (dx/(dist+0.01))*push*3;
      p.y += (dy/(dist+0.01))*push*3;
    }

    if(p.y < -20){
      const np = makeParticle();
      p.x=np.x; p.y=np.y; p.vy=np.vy; p.drift=np.drift; p.phase=np.phase; p.trail=[];
    }

    if(p.trail.length>1){
      ctx.beginPath();
      ctx.moveTo(p.trail[0].x,p.trail[0].y);
      for(let i=1;i<p.trail.length;i++) ctx.lineTo(p.trail[i].x,p.trail[i].y);
      const col = p.hueMix>0.5?PALETTE[0]:PALETTE[1];
      ctx.strokeStyle = col;
      ctx.globalAlpha = 0.18;
      ctx.lineWidth = p.r*0.8;
      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    const c = p.hueMix>0.5?PALETTE[2]:PALETTE[1];
    const grd = ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r*4);
    grd.addColorStop(0, c+'cc');
    grd.addColorStop(1, c+'00');
    ctx.beginPath();
    ctx.fillStyle = grd;
    ctx.arc(p.x,p.y,p.r*3,0,Math.PI*2);
    ctx.fill();

    ctx.beginPath();
    ctx.fillStyle = '#ffffff';
    ctx.globalAlpha = 0.7;
    ctx.arc(p.x,p.y,p.r*0.6,0,Math.PI*2);
    ctx.fill();
    ctx.globalAlpha = 1;
  });

  requestAnimationFrame(draw);
}
draw();
